      "recent0": {
        "text": {
          "type": "string",
          "description": "最近参与过的一条拼单历史摘要。",
          "sampleValue": "生鲜拼单 已成团"
        }
      },
      "recent1": {
        "text": {
          "type": "string",
          "description": "第二条参与过的拼单历史摘要。",
          "sampleValue": "奶茶拼单 已到账"
        }
      },
      "recent2": {
        "text": {
          "type": "string",
          "description": "第三条参与过的拼单历史摘要。",
          "sampleValue": "周末团购 待配送"
        }
      }
    },
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气能力返回的区县名称。",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "天气能力返回的当前温度展示文本。",
            "sampleValue": "21°C"
